Here's a complete example of data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases for CalculateTotal ---
    [TestMethod]
    [DataRow(10.0, 1, 10.0)]
    [DataRow(10.0, 3, 30.0)]
    [DataRow(0.0, 5, 0.0)]
    [DataRow(19.99, 2, 39.98)]
    [DataRow(100.0, 0, 0.0)]
    public void CalculateTotal_WithDataRow_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DataRow: inline test cases for ApplyDiscount ---
    [TestMethod]
    [DataRow(100.0, 10.0, 90.0)]
    [DataRow(200.0, 25.0, 150.0)]
    [DataRow(50.0, 0.0, 50.0)]
    [DataRow(80.0, 100.0, 0.0)]
    [DataRow(0.0, 50.0, 0.0)]
    public void ApplyDiscount_WithDataRow_ReturnsExpected(
        double total, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: method-sourced test cases ---
    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_WithDynamicData_ReturnsExpected(
        decimal price, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(price, quantity);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> CalculateTotalCases()
    {
        yield return new object[] { 15.50m, 4, 62.00m };
        yield return new object[] { 9.99m, 10, 99.90m };
        yield return new object[] { 1000m, 1, 1000m };
    }

    // --- DynamicData: property-sourced test cases ---
    [TestMethod]
    [DynamicData(nameof(ApplyDiscountCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_WithDynamicData_ReturnsExpected(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> ApplyDiscountCases => new[]
    {
        new object[] { 500m, 20m, 400m },
        new object[] { 75m, 50m, 37.5m },
        new object[] { 10m, 0m, 10m },
    };

    // --- Edge case: invalid discount throws ---
    [TestMethod]
    [DataRow(-5.0)]
    [DataRow(101.0)]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discount));
    }
}
```

**Key points:**

- **`[DataRow]`** – best for simple inline values; uses `double` since attributes don't support `decimal` literals.
- **`[DynamicData]`** – use `Method` or `Property` source when you need `decimal`, complex objects, or many cases.
- **`[TestInitialize]`** – sets up a fresh instance per test.
- Edge-case tests validate error paths with `ThrowsException`.

Adjust the method signatures and expected behavior to match your actual `PriceCalculator` implementation.
